var souscalcul = ((msg.th['temperature setpoint'] - msg.th['indoor temperature']) * msg.th['indoor coefficient']) + ((msg.th['indoor temperature'] - msg.th['outdoor temperature']) * msg.th['outdoor coefficient']);
var calculb = (souscalcul / 100 * msg.th['cycle time']);
var calculc = (msg.th['cycle time'] * msg.th['preheat time'] / 100);
calculb = calculb.toFixed(1);
calculc = calculc.toFixed(1);

// positive result for heat request
msg.th.compute = calculb - calculc;

if (msg.th.compute > 0) {
    node.status({
        fill: "red", shape: "ring", text: msg.th.bucket+' heat resquest at '+msg.th.compute
    });
}
if (msg.th.compute <= 0) {
    node.status({
        fill: "green", shape: "ring", text: msg.th.bucket+' at '+msg.th.compute
    });
}


return msg;

// compute temperatures
var interieur = msg.th['indoor temperature'] - msg.th['temperature setpoint'] - 2;
var exterieur = (msg.th['outdoor temperature'] - msg.th['temperature setpoint']) *2;
var compute = interieur + exterieur;
compute = compute.toFixed(1);

msg.th.compute = compute;

//var calcul = msg.th['outdoor temperature'] + msg.th['indoor temperature'] - 2 * msg.th['temperature setpoint'] - 5;
//calcul = calcul.toFixed(1);
//msg.th.compute = calcul;

if (msg.th.compute > 0) {
    node.status({
        fill: "blue", shape: "ring", text: msg.th.bucket+' cool resquest at '+msg.th.compute
    });
}
if (msg.th.compute <= 0) {
    node.status({
        fill: "green", shape: "ring", text: msg.th.bucket+' at '+msg.th.compute
    });
}

return msg;

var msg = msg;
var temperature = 0;

if (typeof msg.temperatures[1] !== 'undefined') {
    temperature = msg.temperatures[1];
}
if (typeof msg.temperatures[0] !== 'undefined') {
    temperature = msg.temperatures[0];
}
if (typeof msg.temperatures[0] !== 'undefined' && typeof msg.temperatures[1] !== 'undefined') {
    temperature = (msg.temperatures[0] + msg.temperatures[1]) / 2;
}

temperature = temperature.toFixed(1);
msg.trigger_payload = temperature;
msg.field = 'outdoor temperature';

return msg;
